// Arduino Sketch
const uint8_t PIN_RED = 10; // Пин для красного светодиода
const uint8_t PIN_YELLOW = 9; // Пин для жёлтого светодиода
const uint8_t PIN_GREEN = 8; // Пин для зелёного светодиода

void setup() {
  pinMode(PIN_RED, OUTPUT); // Инициализация пинов как выход
  pinMode(PIN_YELLOW, OUTPUT);
  pinMode(PIN_GREEN, OUTPUT);
}

void loop() {
  // Красный, жёлтый, зелёный
  digitalWrite(PIN_RED, HIGH); // Включить красный
  delay(7000); // Задержка 7 секунд

  digitalWrite(PIN_YELLOW, HIGH);
  delay(2000); // Задержка 2 секунды

  digitalWrite(PIN_RED, LOW);
  digitalWrite(PIN_YELLOW, LOW);

  digitalWrite(PIN_GREEN, HIGH);
  delay(7000); // Задержка 7 секунд

  digitalWrite(PIN_YELLOW, HIGH);
  delay(2000); // Задержка 2 секунды

  digitalWrite(PIN_GREEN, LOW);
}
